// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['lyrics'], 'Music', 'Get lyrics for a song', async ({ sock, from, msg, args }) => {
  const query = args.join(' ');
  if (!query) return sock.sendMessage(from, { text: 'Usage: .lyrics shape of you' }, { quoted: msg });
  try {
    const [artist, ...titleParts] = query.split('-').map(s => s.trim());
    const title = titleParts.join('-') || artist;
    const searchArtist = titleParts.length ? artist : '';
    const res = await fetch(`https://api.lyrics.ovh/v1/${encodeURIComponent(searchArtist)}/${encodeURIComponent(title)}`);
    const data = await res.json();
    if (!data.lyrics) throw new Error('not found');
    await sock.sendMessage(from, { text: `🎤 *${query}*\n\n${data.lyrics.slice(0, 3500)}` }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Lyrics not found. Try: .lyrics Artist - Song Title' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
